/** Description: dac_convert sets the DAC register based on the input parameter
    dac_value (Uint16). Maximum value for dac_value is 0x400
*/
void dac_convert (UInt16 dac_value)
{	
	CRITICAL; 

	C_ENTER;
	{
		if (dac_value < DAC_MAX_VALUE)
			DACR = ((dac_value << 6) & (0x3FF << 6)) ;
	}
	C_LEAVE;
	
}
